raw_first:
{
 "rules": [
  {
   "rule_id": "KBYY-S2-R01-01",
   "status": "OK",
   "label": "만 19세 미만 실명의 개인",
   "source": {
    "quote": "▪ 만 19세 미만 실명의 개인"
   },
   "condition": {
    "and": [
     {
      "not": {
       "in": [
        {
         "var": "customer.holder_type"
        },
        [
         "UNREGISTERED_ASSOCIATION",
         "REGISTERED_ASSOCIATION",
         "JOINT",
         "CORPORATION"
        ]
       ]
      }
     },
     {
      "var": "customer.is_youth"
     }
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "KBYY-S2-R01-02",
   "status": "OK",
   "label": "개인사업자 및 임의단체 가입 불가",
   "source": {
    "quote": "※ 개인사업자 및 서류미제출 임의단체, 공동명의 가입 불가"
   },
   "condition": {
    "or": [
     {
      "in": [
       {
        "var": "customer.holder_type"
       },
       [
        "SOLE_PROPRIETOR",
        "UNREGISTERED_ASSOCIATION"
       ]
      ]
     },
     {
      "in": [
       {
        "var": "customer.holder_type"
       },
       [
        "JOINT"
       ]
      ]
     }
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "KBYY-S2-R01-03",
   "status": "OK",
   "label": "1인 1계좌",
   "source": {
    "quote": "※「KB Young Youth 청소년통장」을 포함하여 1인 1계좌"
   },
   "condition": {
    "count_distinct_months": {
     "event": "DEPOSIT",
     "within": {
      "month_range": {
       "from": {
        "anchor": "contract.reference_date",
        "offset_months": -12,
        "day": "first"
       },
       "to": {
        "anchor": "contract.reference_date",
        "offset_months": -1,
        "day": "last"
       }
      }
     }
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

