{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R12-01",
   "status": "OK",
   "label": "전자금융 이체수수료 면제",
   "source": {
    "quote": "전자금융(인터넷뱅킹, 폰뱅킹, 모바일뱅킹) 이체수수료(다른 은행으로 보낼 때) | 제한 없음"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "or": [
     {
      "exists": {
       "event": "CARD_USAGE",
       "within": {
        "ref": "$window"
       }
      }
     },
     {
      "and": [
       {
        ">=": [
         {
          "var": "contract.start_date"
         },
         {
          "literal": "2023-11-11"
         }
        ]
       },
       {
        "<": [
         {
          "var": "contract.start_date"
         },
         {
          "literal": "2023-12-11"
         }
        ]
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "EBANK_TRANSFER",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R12-02",
