       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "or": [
     {
      "exists": {
       "event": "CARD_USAGE",
       "within": {
        "ref": "$window"
       }
      }
     },
     {
      "and": [
       {
        ">=": [
         {
          "var": "contract.start_date"
         },
         {
