        "anchor": "contract.reference_date",
        "offset_months": 0,
        "day": "first"
       },
       "to": {
        "anchor": "contract.reference_date",
        "offset_months": 0,
        "day": "last"
       }
      }
     }
    }
   },
   "effect": {
    "type": "RESTRICT",
    "target": "PRODUCT_SWITCH"
   }
  }
 ]
}

