        [
         "WRITTEN",
         "MAIL",
         "E_MAIL",
         "PHONE",
         "FAX",
         "SMS",
         "ELECTRONIC_NOTICE"
        ]
       ]
      }
     },
     {
      "not": {
       ">=": [
