       "anchor": "account.last_transaction_date",
       "offset_years": 5
      }
     }
    ]
   },
   "effect": {
    "type": "RESTRICT",
    "target": "SLEEPING_ACCOUNT_CONTRIBUTION"
   }
  }
 ]
}

